import{register}from"@elementor/frontend-handlers";const initCounter=e=>{if(e.classList.contains("aae-counter-initialized"))return;e.classList.add("aae-counter-initialized");const t=parseFloat(e.getAttribute("data-from"))||0,n=parseFloat(e.getAttribute("data-to"))||100,r=(parseFloat(e.getAttribute("data-duration"))||2e3)/1e3;void 0!==window.gsap&&window.gsap.ScrollTrigger?window.gsap.fromTo(e,{innerHTML:t},{innerHTML:n,duration:r,snap:{innerHTML:1},ease:"power1.out",scrollTrigger:{trigger:e,start:"top 85%",toggleActions:"play none none none"}}):void 0!==window.gsap?window.gsap.fromTo(e,{innerHTML:t},{innerHTML:n,duration:r,snap:{innerHTML:1},ease:"power1.out"}):e.innerHTML=n};register({elementType:"e-aae-a-counter",id:"e-aae-a-counter-handler",callback:({element:e})=>{const t=e.querySelector(".aae-a-counter-number");t&&(t.classList.remove("aae-counter-initialized"),initCounter(t))}});